create or replace function public.require_experience_collaborator_approval()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if new.review_status = 'pending' and old.review_status is distinct from 'pending' then
    if exists (
      select 1
      from public.experience_operators eo
      where eo.experience_id = new.id
        and eo.role = 'participant'
        and eo.approval_status <> 'accepted'
    ) then
      raise exception 'Tutti gli operatori partner devono approvare la collaborazione prima dell''invio a BIMARIS';
    end if;
  end if;
  return new;
end;
$$;

