create or replace function public.record_user_behavior(
  p_event_type text,
  p_content_type text default null,
  p_content_id text default null,
  p_interest_key text default null,
  p_weight numeric default 1,
  p_operator_id text default null,
  p_operator_name text default null,
  p_source_type text default null,
  p_source_id text default null,
  p_action_type text default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user_id uuid := auth.uid();
  v_weight numeric := greatest(-10, least(coalesce(p_weight, 1), 10));
  v_interest_key text := nullif(btrim(p_interest_key), '');
begin
  if v_user_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

