create function public.b2b_guard_approval_consistency()
returns trigger language plpgsql security invoker set search_path = ''
as $$
begin
 if old.approval_status = 'accepted'
    and new.approval_status = 'accepted'
    and new.activity_label is distinct from old.activity_label
 then
  raise exception 'Un accordo accettato richiede un nuovo invito per modificare l attività';
 end if;
 if old.approval_status = 'accepted'
    and new.approval_status = 'pending'
    and new.activity_label is not distinct from old.activity_label
 then
  raise exception 'Non è consentito annullare un accettazione senza modificare l attività';
 end if;
 if new.approval_status is not distinct from old.approval_status
    and new.approved_at is distinct from old.approved_at
 then
  raise exception 'Data di approvazione non modificabile';
 end if;
 return new;
end;
$$;
create trigger b2b_approval_consistency
before update on public.experience_operators
for each row execute function public.b2b_guard_approval_consistency();

