create or replace function public.guard_experience_collaboration_update()
returns trigger language plpgsql set search_path = '' as $$
declare v_uid uuid := (select auth.uid()); v_editor boolean; v_partner boolean;
begin
 if current_user in ('postgres','service_role') then return new; end if;
 if v_uid is null then raise exception 'collaboration_auth_required' using errcode='42501'; end if;
 if (new.experience_id,new.operator_id,new.role,new.created_at,new.invited_by_operator_id) is distinct from (old.experience_id,old.operator_id,old.role,old.created_at,old.invited_by_operator_id) then
 raise exception 'collaboration_identity_immutable' using errcode='42501'; end if;
 select exists(select 1 from public.experiences e join public.operator_memberships m on m.operator_id=e.operator_id where e.id=old.experience_id and m.user_id=v_uid and m.role in ('owner','manager') and e.published=false and e.review_status in ('draft','rejected')) into v_editor;
 select exists(select 1 from public.operator_memberships m where m.operator_id=old.operator_id and m.user_id=v_uid and m.role in ('owner','manager')) into v_partner;
 if new.approval_status is distinct from old.approval_status or new.approved_at is distinct from old.approved_at then
   if not v_partner or old.role <> 'participant' or old.approval_status <> 'pending' or new.approval_status not in ('accepted','rejected') or (new.approval_status='accepted' and new.approved_at is null) or (new.approval_status='rejected' and new.approved_at is not null) or new.activity_label is distinct from old.activity_label then
   raise exception 'collaboration_decision_forbidden' using errcode='42501'; end if;
 else
   if not v_editor then raise exception 'collaboration_edit_forbidden' using errcode='42501'; end if;
 end if;
 return new;
end $$;
drop trigger if exists guard_experience_collaboration_update on public.experience_operators;
create trigger guard_experience_collaboration_update before update on public.experience_operators for each row execute function public.guard_experience_collaboration_update();

CREATE OR REPLACE FUNCTION public.accept_operator_application(p_application_id uuid, p_slug text, p_why_selected text DEFAULT NULL::text, p_publish boolean DEFAULT false)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare
  application_row public.operator_applications%rowtype;
  created_place_id uuid;
  created_operator_id uuid;
  clean_slug text;
begin
  select * into application_row from public.operator_applications where id = p_application_id for update;
  if not found then raise exception 'operator application not found'; end if;
  if application_row.status = 'rejected' then raise exception 'rejected application cannot be accepted'; end if;
  if application_row.status = 'accepted' or application_row.operator_id is not null then raise exception 'accepted application cannot be accepted again'; end if;
  clean_slug := lower(regexp_replace(trim(p_slug), '[^a-zA-Z0-9]+', '-', 'g'));
  clean_slug := trim(both '-' from clean_slug);
  if clean_slug = '' then raise exception 'invalid operator slug'; end if;
  insert into public.places (slug,name,kind,address,google_maps_query,latitude,longitude)
  values ('operatore-' || clean_slug,application_row.business_name,'operator',
  coalesce(application_row.address,application_row.location),
  concat_ws(' ',application_row.business_name,application_row.location),
  application_row.latitude,application_row.longitude)
  on conflict (slug) do update set name=excluded.name,kind='operator',address=excluded.address,
  google_maps_query=excluded.google_maps_query,latitude=excluded.latitude,longitude=excluded.longitude,updated_at=now()
  returning id into created_place_id;
  insert into public.operators (
    slug,name,description,category,address,latitude,longitude,phone,whatsapp,email,website,instagram,
    selection_status,why_selected,published,place_id,vat_number
  ) values (
    clean_slug,application_row.business_name,application_row.description,application_row.category,
    coalesce(application_row.address,application_row.location),application_row.latitude,application_row.longitude,
    application_row.phone,application_row.whatsapp,application_row.email,application_row.website,application_row.instagram,
    'selected',p_why_selected,p_publish,created_place_id,application_row.vat_number
  ) returning id into created_operator_id;
  update public.operator_applications set status='accepted',reviewed_at=now(),
    review_notes=p_why_selected,operator_id=created_operator_id where id=p_application_id;
  return created_operator_id;
end;
$function$;

