CREATE OR REPLACE FUNCTION public.link_operator_to_business_account(p_operator_id uuid,p_account_id uuid,p_owner_user_id uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN
   RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS (
   SELECT 1 FROM public.business_account_memberships m
   WHERE m.account_id=p_account_id AND m.user_id=p_owner_user_id AND m.role='owner'
 ) THEN RAISE EXCEPTION 'account_owner_not_verified' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS (
   SELECT 1 FROM public.operator_memberships m
   WHERE m.operator_id=p_operator_id AND m.user_id=p_owner_user_id AND m.role='owner'
 ) THEN RAISE EXCEPTION 'operator_owner_not_verified' USING ERRCODE='23514'; END IF;
 UPDATE public.operators o SET business_account_id=p_account_id
 WHERE o.id=p_operator_id AND o.business_account_id IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'operator_missing_or_already_linked' USING ERRCODE='23514'; END IF;
 RETURN true;
END $$;
