insert into public.historical_editorial_stories(slug,position,published,protected,content)
values
('medioevo',1,true,true,$story${"key":"medioevo","title":"La Messina medievale","subtitle":"Il porto, i sovrani e le persone che diedero forma alla città","theme":"XII–XIII secolo","intro":["Nel 1184 Ibn Jubayr, viaggiatore e scrittore musulmano originario dell’Andalusia, arriva a Messina e trova una città che quasi fatica a contenere i suoi abitanti. Il viaggiatore andaluso descrive navi provenienti da molti paesi, merci e mercati pieni di attività. Non tutto gli piace: giudica duramente la sporcizia e l’accoglienza. Ma del porto riconosce un vantaggio concreto: anche le grandi imbarcazioni possono accostarsi vicino alla riva.","È una voce che ci restituisce Messina prima delle fotografie e delle distruzioni, quando le sue relazioni con il Mediterraneo sono già parte della vita cittadina. Da quell’approdo arrivano persone; nella città trovano posto istituzioni, si costruiscono edifici, si formano appartenenze che possono durare più a lungo di una vita.","Per seguirne le tracce cominciamo vicino al porto, dall’Annunziata. La chiesa appartiene alla stagione normanna del XII secolo. Il nome con cui la conosciamo, “dei Catalani”, racconta invece un’appartenenza successiva: altri avrebbero legato la propria comunità a un edificio già esistente.","Qui possiamo fermarci. Non per immaginare Ibn Jubayr dentro questa chiesa, ma per incontrare una testimonianza della città del suo tempo."],"chapters":[{"number":1,"title":"PAUSA DI VISITA — Davanti all’Annunziata dei Catalani","placeTitle":"Annunziata dei Catalani","slug":"annunziata-dei-catalani","paragraphs":["La Santissima Annunziata è una chiesa di origine normanna, legata successivamente alla comunità catalana e alla sua confraternita. Il nome attuale ricorda questa appartenenza, non i costruttori del XII secolo.","Se possiamo entrare, riconosciamo la divisione in tre navate e la cupola all’incrocio fra navata e transetto. All’esterno soffermiamoci sull’abside: il loggiato cieco, formato da archetti e colonnine, e l’alternanza delle pietre creano una decorazione geometrica. Nell’architettura normanna gli studiosi riconoscono riferimenti bizantini, arabi e romanici.","Il terremoto del 1908 fece crollare molte costruzioni addossate che la nascondevano; i restauri successivi contribuirono all’aspetto odierno. È una testimonianza medievale restaurata, non un edificio rimasto immutato."],"transition":["La Messina descritta dal viaggiatore appartiene ancora al regno normanno. Dieci anni dopo, nel 1194, la Sicilia viene conquistata da Enrico VI di Svevia, imperatore del Sacro Romano Impero e figlio di Federico Barbarossa. Al suo fianco c’è la moglie, Costanza d’Altavilla, figlia di Ruggero II, il primo re normanno di Sicilia, ed erede della dinastia che aveva governato il regno. Il loro matrimonio lega la casa imperiale sveva alla famiglia dei sovrani normanni; con la conquista di Enrico, questo legame si traduce in un nuovo potere sull’isola.","A Messina il passaggio fra le due dinastie entra anche nella storia della cattedrale: nata in età normanna, viene consacrata nel 1197 alla presenza di Enrico e Costanza, imperatore e imperatrice, re e regina di Sicilia. La chiesa maggiore accoglie così i sovrani nei quali si incontrano la dinastia che l’aveva vista sorgere e quella che governa ora il regno.","Lasciamo l’Annunziata e raggiungiamo il Duomo. Non stiamo passando soltanto da una chiesa a un’altra: arriviamo nel luogo al quale è legato quell’incontro del 1197 fra città, autorità religiosa e dinastia regnante. Prima di proseguire con ciò che accadde in quello stesso settembre, fermiamoci davanti alla cattedrale."]},{"number":2,"title":"PAUSA DI VISITA — Davanti al Duomo","placeTitle":"Duomo di Messina e Tesoro della Cattedrale","slug":"duomo-messina-tesoro-cattedrale","paragraphs":["Il Duomo è la basilica cattedrale dedicata all’Assunta, sede della cattedra del vescovo e principale chiesa della diocesi. Di origine normanna e consacrato nel 1197, conserva questa funzione religiosa attraverso profonde trasformazioni.","Guardiamo la facciata e il portale maggiore, realizzato in fasi fra XIV e XV secolo: la sua decorazione scolpita appartiene a un Medioevo più tardo rispetto alla consacrazione. Nell’interno, quando accessibile, le tre navate conducono verso il transetto e le absidi; colonne e archi scandiscono lo spazio basilicale. La decorazione musiva del settore absidale completa la lettura artistica dell’insieme.","Terremoti e guerra ne hanno imposto ampie ricostruzioni, soprattutto dopo il 1908 e il 1943. Forme, materiali e decorazioni non appartengono tutti alla stessa epoca."],"transition":["Il settembre del 1197 non si chiude con la consacrazione. Il 28 Enrico VI muore proprio a Messina. La città che ha ospitato il sovrano per la cerimonia diventa anche il luogo della sua morte. Il regno entra in una fase nuova; il rapporto fra la monarchia e Messina proseguirà nella generazione successiva con il loro figlio, Federico II.","Per ritrovare Federico II nella vita della città, lasciamo il Duomo e dirigiamoci verso Santa Maria Alemanna. Questa chiesa faceva parte di un complesso dell’Ordine teutonico che comprendeva anche un ospedale: un luogo di preghiera e di assistenza, inserito nei collegamenti che univano Messina agli altri porti del Mediterraneo.","Una disposizione di Federico II, datata dagli editori al 1219, ci aiuta a capire come veniva sostenuta questa presenza. L’Ordine poteva inviare beni da Palermo alla propria sede di Messina, oppure verso Oltremare, senza pagare il portulatico, il tributo portuale. La «casa» messinese citata nel documento è la sede della comunità teutonica: Santa Maria Alemanna era la chiesa del suo complesso.","Dietro quella concessione possiamo riconoscere una necessità concreta: far arrivare ciò che serviva a mantenere la comunità e le sue attività. Il porto, dal quale è cominciato il nostro racconto, torna così nella vita della città anche attraverso gli approvvigionamenti di un’istituzione religiosa e assistenziale.","Ora che siamo davanti a Santa Maria Alemanna, fermiamoci a osservare la chiesa superstite di quel complesso. Riprenderemo poi il filo della storia, passando dal sostegno del sovrano a quello delle persone della città."]},{"number":3,"title":"PAUSA DI VISITA — A Santa Maria Alemanna","placeTitle":"Santa Maria Alemanna","slug":"santa-maria-alemanna","paragraphs":["Santa Maria Alemanna è un’ex chiesa medievale legata all’Ordine teutonico e a un complesso che comprendeva anche un ospedale. Oggi è utilizzata come spazio per attività culturali: la sua funzione è cambiata, mentre l’edificio conserva la memoria della presenza religiosa e assistenziale.","Il carattere gotico si riconosce nelle arcate a sesto acuto e nei pilastri a fascio. Se possiamo osservarne l’interno, seguiamo le tre navate fino alle absidi e soffermiamoci sui capitelli scolpiti: sono dettagli che animano la struttura in pietra.","Portale ricollocato e copertura richiedono di distinguere le parti antiche dagli interventi di restauro. Il documento del 1219 riguarda la casa dell’Ordine, non stabilisce l’anno di costruzione di ogni parte della chiesa."],"transition":["La casa messinese poteva dunque beneficiare di condizioni favorevoli per ricevere beni. Perché una presenza religiosa durasse, però, contavano anche le persone che sceglievano di sostenerla nel luogo in cui si stabiliva. Nel Duecento, la storia dei Frati Minori ci permette di seguire proprio questo contributo della società messinese.","Le ricostruzioni storiche del cantiere di San Francesco ricordano tre donne della nobiltà cittadina: Violante Palizzi, Eleonora da Procida e Beatrice Belfiore. I loro nomi si affiancano a quelli dei religiosi nella storia della costruzione. Il 1254 è un riferimento ricorrente per lo sviluppo della chiesa; la ricostruzione diocesana ricorda anche una prima pietra benedetta da Alessandro IV a Napoli nel 1255.","Non tutto comincia o finisce in queste due date. La presenza dei frati e il grande cantiere hanno fasi differenti. Ma il sostegno ricordato dalle fonti ci permette di vedere la città anche dalla parte di chi contribuisce a costruire un nuovo luogo, oltre che da quella del sovrano che concede un’esenzione.","Sono iniziative diverse, non un’opera comune dei due ordini. A tenerle insieme è il radicamento nella stessa Messina: una casa da mantenere, una comunità che si insedia, persone che sostengono una costruzione.","È per incontrare l’esito di questa seconda vicenda che proseguiamo fino a San Francesco all’Immacolata. Qui la storia di quel sostegno diventa la ragione per fermarci davanti alla chiesa e osservarne le dimensioni."]},{"number":4,"title":"PAUSA DI VISITA — A San Francesco all’Immacolata","placeTitle":"San Francesco all'Immacolata","slug":"san-francesco-immacolata","paragraphs":["San Francesco all’Immacolata è una chiesa francescana di origine duecentesca, oggi santuario diocesano, legata al convento dei Frati Minori Conventuali. Alla storia dei religiosi si sono aggiunti nel tempo il patronato cittadino, sepolture e la devozione all’Immacolata.","Se possiamo entrare, osserviamo la grande aula unica, l’arco a sesto acuto verso il transetto e le alte finestre. All’esterno cerchiamo il settore delle tre absidi. La scala dello spazio e questi elementi aiutano a riconoscere il linguaggio gotico del complesso, senza attribuire al Duecento tutto ciò che vediamo.","Trasformazioni barocche, incendio del 1884 e terremoto del 1908 ne hanno cambiato l’aspetto. Absidi e portali furono rimontati nella ricostruzione: l’edificio attuale comprende materiali recuperati e parti rifatte."],"transition":[]}],"conclusion":["Il cantiere francescano aggiunge un nuovo riferimento alla città e altri nomi alla sua storia. Sono questi gesti di sostegno, accanto alle decisioni dei sovrani e alle relazioni degli ordini religiosi, a dare consistenza alla Messina che abbiamo attraversato.","Siamo partiti dalla città portuale osservata da un viaggiatore. Vi abbiamo incontrato una cattedrale consacrata alla presenza dei sovrani, una casa collegata a invii che attraversavano il mare, una chiesa sostenuta da persone della società cittadina. Nei luoghi dove ci siamo fermati, queste vicende hanno lasciato riferimenti riconoscibili, anche attraverso le trasformazioni dei secoli successivi.","Il porto spiega perché Messina fosse raggiunta da tante relazioni. La storia delle persone e delle istituzioni ci ha mostrato come alcune di esse presero posto nella città. È con questa storia in mente che possiamo tornare a guardare i monumenti, riconoscendo dietro le costruzioni le presenze che contribuirono a farle vivere."]}$story$::jsonb),
('cinquecento',2,true,true,$story${"key":"cinquecento","title":"La città del Cinquecento","subtitle":"Un porto da difendere, una città da rappresentare","theme":"XVI secolo","intro":["Per entrare nella Messina del Cinquecento, cominciamo dalla sua soglia. La falce del porto ripara l'approdo, ma lascia un ingresso da sorvegliare. Sulla sua estremità sorge un monastero: una comunità religiosa occupa il punto che la monarchia vuole trasformare in difesa militare.","È da questa sovrapposizione di esigenze che prende avvio la nostra storia. In pochi decenni, Messina cambia il margine del porto e affida a uno scultore il compito di dare un'immagine monumentale all'acqua e al mare. La fortezza e le fontane non nascono da un solo progetto. A unirle sono le scelte di una città che appartiene alla monarchia asburgica e possiede istituzioni capaci di commissionare opere nelle quali riconoscersi.","Nel 1535 Carlo V d’Asburgo, imperatore del Sacro Romano Impero e re di Spagna, arriva a Messina. Dopo la sua visita si decide di trasferire il monastero del Santissimo Salvatore per trasformarne le fabbriche in una fortificazione. La priorità militare interviene su uno spazio già abitato e organizzato: per i religiosi comporta il cambiamento della propria sede, per il porto una diversa destinazione della sua punta estrema.","Il passaggio richiede tempo. La chiesa viene inizialmente risparmiata; nel 1549 un fulmine provoca l'esplosione del vicino deposito di polvere e la distrugge. Il nome del Santissimo Salvatore rimane legato al forte, mentre il complesso religioso attraversa la vicenda del trasferimento.","Per capire che cosa significasse presidiare questa soglia, fermiamo qui il racconto. Il punto da osservare è proprio quello sul quale si è concentrata la decisione militare."],"chapters":[{"number":1,"title":"Pausa di visita — Forte del Santissimo Salvatore","placeTitle":"Forte del Santissimo Salvatore","slug":"forte-santissimo-salvatore","paragraphs":["Il Santissimo Salvatore è una fortezza cinquecentesca sulla punta della penisola di San Raineri, all'ingresso del porto. Sorge nell'area del precedente monastero; le sue strutture appartengono alla successiva organizzazione militare del luogo.","Guardiamo soprattutto il rapporto fra la fortificazione e l'acqua: i bastioni ospitavano artiglierie rivolte verso lo Stretto e l'imboccatura portuale. Qui la forma dell'edificio si comprende attraverso la funzione difensiva, nella disposizione delle masse murarie e delle postazioni. Il segno verticale della stele della Madonna della Lettera appartiene invece al Novecento: non faceva parte del forte cinquecentesco.","La posizione si può comprendere anche osservando il complesso dal porto. La visita interna richiede una verifica preventiva delle condizioni di accesso alla base navale."],"transition":["Il porto ha dunque cambiato una presenza religiosa in presidio militare. Ma la Messina nella quale si costruisce il forte vive anche del lavoro dei mercanti e degli artigiani della seta. Già nel 1520 questi mestieri hanno una propria istituzione, il Consolato dell’arte della seta: controlla la qualità dei prodotti, regola il lavoro e risolve le controversie tra chi lavora la seta e chi la commercia. Il 18 aprile 1530 Carlo V conferma i capitoli, cioè le disposizioni che ne regolano l’organizzazione. Accanto alla città che difende il porto, prende così forma quella che tutela e organizza le proprie attività produttive.","Alla difesa dell'approdo si affiancano altre necessità cittadine. Una riguarda l'acqua da condurre in città. È questa vicenda, distinta da quella militare, a portarci dal margine del porto alla piazza del Duomo.","L'acquedotto porta a Messina le acque del Camaro. Il Senato sceglie di celebrare l'impresa affidandole una presenza nella piazza della cattedrale. Nel 1547 chiama Giovanni Angelo Montorsoli; nel 1553 la Fontana di Orione è compiuta.","Dietro queste date ci sono due lavori differenti: condurre l'acqua e costruire il monumento che la celebra. La fontana dà alla seconda impresa un linguaggio fatto di figure, vasche e iscrizioni. Il corso d'acqua messinese compare accanto a Nilo, Tevere ed Ebro; in alto, Orione richiama le origini mitiche della città.","Non stiamo leggendo la storia reale di un fondatore. Stiamo seguendo una scelta del Cinquecento: usare quel mito per rappresentare Messina nel luogo in cui il risultato dell'opera idrica diventa visibile. Arrivati davanti alla fontana, possiamo riconoscere come lo scultore abbia costruito questa celebrazione."]},{"number":2,"title":"Pausa di visita — Fontana di Orione","placeTitle":"Fontana di Orione","slug":"fontana-di-orione","paragraphs":["È una fontana monumentale rinascimentale, realizzata da Montorsoli per il Senato e completata nel 1553. Celebra l'acquedotto del Camaro ed è rimasta legata alla piazza del Duomo per la quale fu concepita.","Seguiamone la composizione dal basso verso l'alto: il basamento poligonale, i fiumi distesi attorno alla grande vasca, le figure che sostengono le coppe superiori e infine Orione. La struttura sale come una piramide, ma la successione dei corpi e delle vasche ne articola il profilo. Il marmo scolpito trasforma l'opera idraulica in una composizione figurativa complessa, nella quale il mito cittadino occupa il punto più alto.","Per comprenderla basta trattenere questo rapporto: alla base l'acqua del territorio entra in una geografia di fiumi; al culmine la città riconosce il proprio fondatore leggendario."],"transition":["L’acqua del Camaro arriva in città e, nella piazza del Duomo, diventa anche spettacolo. La Fontana di Orione dà una forma monumentale a questa conquista: il racconto dell’acqua si intreccia con quello delle origini di Messina, portando nella vita quotidiana della piazza la figura del suo mitico fondatore.","Pochi anni dopo Montorsoli torna a dare forma all'acqua, questa volta guardando al mare. Per Messina il soggetto è immediatamente riconoscibile: lo Stretto possiede già i nomi di Scilla e Cariddi. Nel 1557 queste figure entrano nella Fontana del Nettuno, ma vi compaiono incatenate.","Rispetto a Orione cambia l'equilibrio del racconto. Non si celebra l'arrivo di una risorsa dal territorio: si mostra un dio che domina le forze attribuite al mare. La lettura proposta dal museo messinese riconosce nella composizione un'allusione alla protezione della città sotto il dominio asburgico.","Nella figura di Nettuno, Messina mette in scena il proprio rapporto con il mare. Il dio domina Scilla e Cariddi, trasformando le forze temute dello Stretto in una composizione monumentale: il paesaggio e il mito diventano il linguaggio con cui la città rappresenta la propria grandezza. Per leggerla, raggiungiamo la fontana nella sua sistemazione attuale, ricordando che anche il rapporto del monumento con la città ha una storia."]},{"number":3,"title":"Pausa di visita — Fontana del Nettuno","placeTitle":"Fontana del Nettuno","slug":"fontana-del-nettuno","paragraphs":["La fontana di Montorsoli, del 1557, è oggi in piazza Unità d'Italia. Nel 1934 fu trasferita e ruotata rispetto alla collocazione precedente: l'orientamento attuale non va attribuito automaticamente al progetto cinquecentesco.","Al centro si alza Nettuno; ai lati, Scilla e Cariddi sono trattenute in catene. Qui domina la grande statuaria: confrontandola con Orione, riconosciamo una composizione che affida soprattutto alla figura eretta del dio il proprio slancio. La statua di Nettuno e quella di Scilla all'aperto sono copie ottocentesche; gli originali di Montorsoli sono conservati al Museo Regionale. Questa distinzione riguarda quelle due figure, non autorizza a definire tutta la fontana una copia.","Soffermiamoci sul contrasto fra la posizione dominante del dio e i mostri ai suoi piedi: è il rapporto visivo che sostiene la lettura politica dell'opera."],"transition":[]}],"conclusion":["La storia arriva qui al suo punto d'incontro. Sulla falce del porto abbiamo seguito una decisione militare che cambia la sede di una comunità; in piazza Duomo una committenza cittadina che celebra l'acqua del Camaro; davanti a Nettuno il mare dello Stretto trasformato in immagine del potere.","Sono interventi diversi, con tempi e finalità propri. Insieme rendono riconoscibile questa Messina del Cinquecento: una città nella quale la monarchia interviene sulla difesa dell'approdo e il Senato affida alla scultura il compito di dichiarare risultati e ambizioni. Dopo averne seguito le vicende, bastioni e fontane conservano anche le persone e le istituzioni che ne decisero l'esistenza."]}$story$::jsonb),
('1908-rinascita',3,true,true,$story${"key":"1908-rinascita","title":"La città che rinasce","subtitle":"Dopo il 1908: salvare, abitare, ritrovare il centro","theme":"Dopo il 1908","intro":["Il 28 dicembre 1908 il terremoto e il maremoto spezzano la vita di Messina. Alle distruzioni seguono necessità che non possono attendere gli stessi tempi: trovare riparo, recuperare il patrimonio, riprendere le attività, decidere dove e come costruire.","Per seguire questa storia partiremo dal museo e arriveremo alla piazza del Duomo, passando per la Galleria. Ma fra un edificio e l'altro dovremo tenere presente anche ciò che i monumenti non mostrano immediatamente: la vita in sistemazioni provvisorie e la distanza fra un'inaugurazione e una città nuovamente abitabile per tutti.","Dopo il disastro, Antonino Salinas e i suoi collaboratori partecipano al recupero di opere e materiali dagli edifici colpiti. Una parte del patrimonio viene riunita nell'area del San Salvatore dei Greci. Le opere lasciano le chiese e i palazzi per i quali erano nate; conservarle richiede ora una nuova destinazione.","Il museo messinese esisteva già prima del terremoto. Il recupero ne cambia però il patrimonio e le esigenze. Dal 1911 la filanda Mellinghoff ospita le raccolte; nel 1914 viene istituito il Museo Nazionale. Il salvataggio non ha ricostruito gli ambienti perduti, ma ha reso possibile trasmetterne una parte.","La nostra prima sosta serve a riconoscere proprio questa differenza fra un'opera rimasta nel suo luogo e un'opera sopravvissuta grazie al trasferimento."],"chapters":[{"number":1,"title":"Pausa di visita — Museo Regionale «Maria Accascina»","placeTitle":"Museo Regionale Interdisciplinare di Messina — MuMe","slug":"mume-museo-regionale-messina","paragraphs":["Il MuMe è il museo nel quale si raccoglie una parte essenziale del patrimonio artistico messinese. Le sue collezioni comprendono il nucleo civico precedente al 1908 e numerose opere recuperate dopo il terremoto. L'edificio espositivo attuale, inaugurato nel 2017, va distinto dalla filanda che aveva ospitato le raccolte nel primo Novecento.","Il complesso comprende spazi interni ed esterni con elementi architettonici provenienti dalla città. Nel percorso pitture, sculture e manufatti di diversa natura sono accostati secondo periodi e contesti. Per questa visita, soffermiamoci soprattutto sui frammenti di architettura e sulle provenienze indicate nelle didascalie: aiutano a restituire un indirizzo alle opere e a capire quali edifici della Messina precedente non esistano più nella stessa forma.","Il museo custodisce anche capolavori di Antonello da Messina e Caravaggio. La loro presenza non esaurisce il significato della raccolta: accanto alle grandi opere, un frammento può conservare la memoria materiale di una strada o di un edificio perduto."],"transition":["Le opere hanno trovato un ricovero. Nello stesso tempo, le persone e le istituzioni devono trovare spazi nei quali vivere e riprendere le attività. I due lavori procedono insieme: la ricostruzione non aspetta che i recuperi siano conclusi, né chi cerca un alloggio può aspettare i nuovi monumenti.","Le sistemazioni nate per l'emergenza non scompaiono tutte con l'avvio dei cantieri. Alcune rimangono abitate per decenni. Il loro protrarsi è parte della storia messinese della ricostruzione: il provvisorio diventa una condizione che supera i tempi per i quali era stato pensato.","Anche l'Università deve trovare il modo di continuare. Nel 1909 se ne discutono la soppressione o il trasferimento; nell'anno accademico 1909–1910 le attività riprendono in strutture provvisorie. Le lezioni possono ricominciare prima che esista una sede definitiva. È una continuità concreta, ottenuta in condizioni diverse da quelle precedenti al terremoto.","Nel 1911 viene approvato il piano regolatore legato a Luigi Borzì. Strade e servizi entrano nel disegno della città futura, ma fra il piano e la sua attuazione si collocano gli anni dei progetti e dei lavori. Approvare la forma di Messina non significa aver già dato a tutti uno spazio stabile nel quale abitarla.","È con questa distanza in mente che torniamo verso il centro. Negli anni Venti due cantieri, quello del Duomo e quello della Galleria, rendono visibili risposte differenti alla stessa distruzione.","Il Duomo riapre al culto nel 1929. Per la comunità religiosa torna utilizzabile la cattedrale; per la città torna riconoscibile una presenza che occupava quel luogo da secoli. La continuità passa però attraverso una ricostruzione: le forme antiche che si vogliono ritrovare richiedono lavoro contemporaneo.","Prima di proseguire verso gli spazi commerciali della nuova Messina, fermiamoci davanti a questo edificio. È qui che possiamo vedere quanto sia diversa la storia di un monumento ricostruito da quella di un edificio rimasto intatto."]},{"number":2,"title":"Pausa di visita — Duomo di Messina","placeTitle":"Duomo di Messina e Tesoro della Cattedrale","slug":"duomo-messina-tesoro-cattedrale","paragraphs":["È la cattedrale di Messina, nata in età normanna e più volte trasformata. L'edificio attuale comprende la ricostruzione seguita al 1908 e gli interventi resi necessari dalle distruzioni del 1943.","All'esterno osserviamo i portali e l'articolazione della facciata; all'interno la pianta basilicale, con tre navate scandite dalle colonne, le arcate ogivali e le absidi. Il soffitto ligneo, i mosaici e le opere conservate appartengono a una storia di recuperi e rifacimenti: l'aspetto che richiama il Medioevo non equivale all'integrale sopravvivenza della materia medievale.","È una chiesa tuttora destinata al culto. Le sue dimensioni e la successione delle navate rendono percepibile la funzione collettiva che la ricostruzione volle restituire a questo luogo."],"transition":["Nel 1929 il Duomo torna dunque alla sua funzione. Negli stessi anni, poco lontano, si realizza una soluzione urbana diversa. Fra il 1924 e il 1929, su progetto di Camillo Puglisi Allegra, viene costruita la Galleria Vittorio Emanuele III: uno spazio coperto attorno al quale si riuniscono commercio, uffici e residenze.","Il confronto non richiede di immaginare un unico cantiere. Nella cattedrale si cerca continuità con una presenza storica; nella Galleria si progetta un ambiente nuovo per le attività del centro. Portiamo con noi questa differenza fino al suo ingresso da piazza Antonello."]},{"number":3,"title":"Pausa di visita — Galleria Vittorio Emanuele III","placeTitle":"Galleria Vittorio Emanuele III","slug":"galleria-vittorio-emanuele-iii","paragraphs":["La Galleria è un edificio civile della ricostruzione, progettato per unire percorsi coperti e funzioni commerciali, lavorative e residenziali. Non è una strada antica semplicemente coperta dopo il terremoto: appartiene al nuovo disegno del centro.","Dall'ingresso monumentale seguiamo i tre bracci verso lo spazio centrale esagonale, coperto da una cupola vetrata. La luce dall'alto e la decorazione, descritta nelle fonti come neorococò, danno rappresentatività a un ambiente destinato alla vita urbana. Fermiamoci al centro: da qui l'incontro dei passaggi rende comprensibile l'organizzazione dell'edificio meglio di una sola veduta della facciata.","La funzione originaria spiega l'accostamento fra spazio pubblico di attraversamento e ambienti disposti intorno: la Galleria deve essere letta anche come un organismo di attività, non soltanto come un interno decorato."],"transition":["Nel medesimo periodo tornano così luoghi del culto e si costruiscono nuovi spazi civili. Questi risultati non chiudono la questione degli alloggi, ma danno al centro funzioni nuovamente riconoscibili. La storia prosegue negli anni Trenta accanto alla cattedrale, dove si realizza un nuovo segno pubblico: il campanile con l'orologio astronomico.","Nel 1933 entra in funzione l'orologio realizzato dalla ditta Ungerer di Strasburgo. La piazza dispone ora di un sistema che misura il tempo e mette in movimento figure e rappresentazioni legate anche alla memoria cittadina.","La torre non è la semplice ricomposizione di un campanile abbattuto dal sisma del 1908: il precedente era stato demolito nel 1863. È una realizzazione novecentesca che si affianca alla cattedrale ricostruita. Torniamo nella piazza per osservare questa ulteriore scelta."]},{"number":4,"title":"Pausa di visita — Campanile e orologio astronomico","placeTitle":"Campanile del Duomo e Orologio Astronomico","slug":"campanile-orologio-astronomico-messina","paragraphs":["Il campanile è la torre novecentesca del Duomo. Ospita campane, quadranti e un complesso meccanismo astronomico e figurativo, realizzato nel 1933. La sua funzione unisce il tempo misurato, i richiami religiosi e una rappresentazione pubblica della memoria messinese.","Guardiamo i diversi livelli: la struttura della torre organizza aperture e gruppi figurati lungo la sua altezza. A mezzogiorno alcuni automi si muovono; il loro funzionamento aggiunge suoni e gesti a ciò che negli altri momenti osserviamo immobile. Le rappresentazioni religiose e tradizionali vanno riconosciute come tali, senza trasformarle tutte in testimonianze di avvenimenti storici.","Il rapporto con la cattedrale è immediato nello spazio della piazza, ma torre, meccanismo e forme che richiamano epoche precedenti appartengono alla storia della ricostruzione."],"transition":[]}],"conclusion":["Il 1933 ci offre una data per l'orologio, non una data finale per la rinascita di Messina. Alcune sistemazioni provvisorie continuano a essere abitate; nel 1943 i bombardamenti provocano nuove distruzioni e colpiscono ancora il Duomo.","Abbiamo seguito lavori che non avanzano con lo stesso passo: raccogliere opere, riprendere le lezioni, abitare, ricostruire una cattedrale, aprire una galleria. Il museo conserva parte di ciò che ha perduto il proprio luogo; nel centro ritroviamo un edificio religioso ricostruito e un ambiente civile nuovo; nella piazza un orologio del Novecento dà forma al tempo pubblico.","La loro storia rimane incompleta se dimentichiamo chi doveva usare Messina mentre veniva rifatta. È la presenza di quella vita, precedente alle inaugurazioni e più lunga dei cantieri celebrati, a tenere insieme questi luoghi."]}$story$::jsonb)
on conflict (slug) do nothing;

create or replace function public.manage_historical_editorial(
  p_action text, p_actor uuid, p_workspace uuid, p_entry uuid, p_version integer, p_data jsonb
) returns uuid language plpgsql set search_path to '' as $$
declare
  w public.editorial_workspaces;
  existing public.historical_editorial_stories;
  chapter jsonb;
  public_slug text;
begin
  if p_actor is null then raise exception 'editorial-invalid-actor'; end if;
  if p_action='create' then
    if p_entry is not null then
      select * into strict existing from public.historical_editorial_stories where id=p_entry;
    end if;
    insert into public.editorial_workspaces(model,entry_id,draft)
    values ('historical',p_entry,coalesce(existing.content,'{}'::jsonb))
    on conflict (model,entry_id) do nothing returning * into w;
    if w.id is null then
      select * into strict w from public.editorial_workspaces where model='historical' and entry_id=p_entry;
      return w.id;
    end if;
  else
    select * into strict w from public.editorial_workspaces where id=p_workspace and model='historical' for update;
    if w.archived or w.version is distinct from p_version then raise exception 'editorial-conflict'; end if;
    if w.entry_id is not null then
      select * into strict existing from public.historical_editorial_stories where id=w.entry_id for update;
      if existing.protected and p_action in ('publish','withdraw','archive') then raise exception 'editorial-protected'; end if;
    end if;
    case p_action
      when 'save' then
        w.draft := jsonb_build_object('title',p_data->'title','subtitle',p_data->'subtitle',
          'theme',p_data->'theme','intro',p_data->'intro','chapters',p_data->'chapters','conclusion',p_data->'conclusion');
      when 'publish' then
        if nullif(btrim(w.draft->>'title'),'') is null or nullif(btrim(w.draft->>'subtitle'),'') is null
          or nullif(btrim(w.draft->>'theme'),'') is null
          or coalesce(jsonb_array_length(w.draft->'intro'),0)=0
          or coalesce(jsonb_array_length(w.draft->'chapters'),0)=0
          or coalesce(jsonb_array_length(w.draft->'conclusion'),0)=0 then
          raise exception 'editorial-fields-required';
        end if;
        for chapter in select value from jsonb_array_elements(w.draft->'chapters') loop
          if nullif(btrim(chapter->>'title'),'') is null or coalesce(jsonb_array_length(chapter->'paragraphs'),0)=0 then
            raise exception 'editorial-fields-required';
          end if;
          if nullif(chapter->>'slug','') is not null and not exists (
            select 1 from public.culture_entries where published and slug=chapter->>'slug'
          ) then raise exception 'editorial-invalid-culture-link'; end if;
        end loop;
        public_slug := coalesce(existing.slug,p_data->>'slug');
        if public_slug is null or public_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then raise exception 'editorial-invalid-slug'; end if;
        if w.entry_id is null then
          insert into public.historical_editorial_stories(slug,published,content)
          values(public_slug,true,w.draft || jsonb_build_object('key',public_slug)) returning id into w.entry_id;
        else
          update public.historical_editorial_stories
          set content=w.draft || jsonb_build_object('key',public_slug),published=true where id=w.entry_id;
        end if;
      when 'withdraw','archive' then
        update public.historical_editorial_stories set published=false where id=w.entry_id;
        w.archived := p_action='archive';
      else raise exception 'editorial-invalid-action';
    end case;
    update public.editorial_workspaces set draft=w.draft,entry_id=w.entry_id,
      archived=w.archived,version=w.version+1 where id=w.id returning * into w;
  end if;
  insert into public.editorial_activity(workspace_id,actor,action,version) values(w.id,p_actor,p_action,w.version);
  return w.id;
end $$;
revoke all on function public.manage_historical_editorial(text,uuid,uuid,uuid,integer,jsonb) from public,anon,authenticated;
grant execute on function public.manage_historical_editorial(text,uuid,uuid,uuid,integer,jsonb) to service_role;

-- DS-QA-SEC-04/V2. Staging-only authorized execution; no data or RLS changes.
-- Requires PostgreSQL 17. Apply only via a verified Staging connection.
-- Recovery: docs/qa/DT-QA-SEC-01-R04-rollback.sql (separate authorization for restoration).
DO $sec_r04$
DECLARE
  t text; r text; p text; q text; a text; b text;
  before_data jsonb := '{}'::jsonb; after_data jsonb := '{}'::jsonb;
  before_acl jsonb; after_acl jsonb; before_policies text; after_policies text;
  names text[] := ARRAY['culture_entries','culture_images','stories','story_images','villages','village_sources','story_editorial_context'];
  excess text[] := ARRAY['INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER','MAINTAIN'];
BEGIN
  IF current_user <> 'postgres' OR current_setting('server_version_num')::integer < 170000 THEN
    RAISE EXCEPTION 'SEC-R04: unexpected executor or PostgreSQL version';
  END IF;
  -- Serialize against concurrent editorial writers during the short transaction.
  LOCK TABLE public.culture_entries, public.culture_images, public.stories, public.story_images, public.villages, public.village_sources, public.story_editorial_context IN SHARE ROW EXCLUSIVE MODE;
  FOREACH t IN ARRAY names LOOP
    q := format('public.%I',t);
    IF NOT EXISTS (SELECT 1 FROM pg_class WHERE oid=q::regclass AND relrowsecurity AND relowner='postgres'::regrole) THEN
      RAISE EXCEPTION 'SEC-R04: unexpected owner/RLS on %',t;
    END IF;
    FOREACH r IN ARRAY ARRAY['anon','authenticated'] LOOP
      IF NOT has_table_privilege(r,q,'SELECT') THEN RAISE EXCEPTION 'SEC-R04: missing SELECT on % for %',t,r; END IF;
      FOREACH p IN ARRAY excess LOOP
        IF NOT has_table_privilege(r,q,p) THEN RAISE EXCEPTION 'SEC-R04: unexpected precondition % % %',t,r,p; END IF;
      END LOOP;
    END LOOP;
    EXECUTE format('SELECT md5(coalesce(string_agg(to_jsonb(x)::text, E''\\n'' ORDER BY to_jsonb(x)::text),'''')) FROM public.%I x',t) INTO a;
    before_data := before_data || jsonb_build_object(t,a);
  END LOOP;
  SELECT jsonb_agg(jsonb_build_array(c.relname,a.grantor,a.grantee,a.privilege_type,a.is_grantable) ORDER BY c.relname,a.grantor,a.grantee,a.privilege_type)
    INTO before_acl FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
    CROSS JOIN LATERAL aclexplode(c.relacl) a
    WHERE n.nspname='public' AND c.relname=ANY(names) AND a.grantee NOT IN ('anon'::regrole,'authenticated'::regrole);
  SELECT md5(string_agg(to_jsonb(z)::text,E'\n' ORDER BY tablename,policyname)) INTO before_policies FROM pg_policies z WHERE schemaname='public' AND tablename=ANY(names);
  REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER, MAINTAIN ON TABLE public.culture_entries, public.culture_images, public.stories, public.story_images, public.villages, public.village_sources, public.story_editorial_context FROM anon, authenticated;
  FOREACH t IN ARRAY names LOOP
    q := format('public.%I',t);
    FOREACH r IN ARRAY ARRAY['anon','authenticated'] LOOP
      IF NOT has_table_privilege(r,q,'SELECT') THEN RAISE EXCEPTION 'SEC-R04: SELECT lost % %',t,r; END IF;
      FOREACH p IN ARRAY excess LOOP
        IF has_table_privilege(r,q,p) THEN RAISE EXCEPTION 'SEC-R04: residual privilege % % %',t,r,p; END IF;
      END LOOP;
    END LOOP;
    EXECUTE format('SELECT md5(coalesce(string_agg(to_jsonb(x)::text, E''\\n'' ORDER BY to_jsonb(x)::text),'''')) FROM public.%I x',t) INTO b;
    after_data := after_data || jsonb_build_object(t,b);
  END LOOP;
  SELECT jsonb_agg(jsonb_build_array(c.relname,a.grantor,a.grantee,a.privilege_type,a.is_grantable) ORDER BY c.relname,a.grantor,a.grantee,a.privilege_type)
    INTO after_acl FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
    CROSS JOIN LATERAL aclexplode(c.relacl) a
    WHERE n.nspname='public' AND c.relname=ANY(names) AND a.grantee NOT IN ('anon'::regrole,'authenticated'::regrole);
  SELECT md5(string_agg(to_jsonb(z)::text,E'\n' ORDER BY tablename,policyname)) INTO after_policies FROM pg_policies z WHERE schemaname='public' AND tablename=ANY(names);
  IF before_data IS DISTINCT FROM after_data OR before_acl IS DISTINCT FROM after_acl OR before_policies IS DISTINCT FROM after_policies THEN
    RAISE EXCEPTION 'SEC-R04: integrity, service privileges or policy mismatch';
  END IF;
END
$sec_r04$;

-- DT-REL-SEC-01: protect review metadata and source identity; validate applied gallery.
CREATE OR REPLACE FUNCTION public.guard_experience_review_metadata()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path TO '' AS $fn$
BEGIN
  IF current_user NOT IN ('anon','authenticated') THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.review_notes IS NOT NULL OR NEW.reviewed_at IS NOT NULL
       OR NEW.review_sections IS DISTINCT FROM '{}'::jsonb
       OR NEW.review_snapshot IS DISTINCT FROM '{}'::jsonb
    THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='review-metadata-protected'; END IF;
  ELSE
    IF NEW.review_notes IS DISTINCT FROM OLD.review_notes
       OR NEW.reviewed_at IS DISTINCT FROM OLD.reviewed_at
       OR NEW.review_sections IS DISTINCT FROM OLD.review_sections
       OR NEW.review_snapshot IS DISTINCT FROM OLD.review_snapshot
    THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='review-metadata-protected'; END IF;
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.operator_id IS DISTINCT FROM OLD.operator_id
    THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='experience-identity-protected'; END IF;
  END IF;
  RETURN NEW;
END;
$fn$;

CREATE OR REPLACE FUNCTION public.guard_experience_revision_metadata()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path TO '' AS $fn$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.experience_id IS DISTINCT FROM OLD.experience_id
       OR NEW.operator_id IS DISTINCT FROM OLD.operator_id
    THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='revision-identity-protected'; END IF;
  END IF;
  IF current_user NOT IN ('anon','authenticated') THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.review_notes IS NOT NULL OR NEW.reviewed_at IS NOT NULL OR NEW.applied_at IS NOT NULL
       OR NEW.review_sections IS DISTINCT FROM '{}'::jsonb
    THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='review-metadata-protected'; END IF;
  ELSE
    IF NEW.review_notes IS DISTINCT FROM OLD.review_notes
       OR NEW.reviewed_at IS DISTINCT FROM OLD.reviewed_at
       OR NEW.applied_at IS DISTINCT FROM OLD.applied_at
       OR NEW.review_sections IS DISTINCT FROM OLD.review_sections
    THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='review-metadata-protected'; END IF;
  END IF;
  RETURN NEW;
END;
$fn$;

CREATE OR REPLACE FUNCTION public.guard_applied_experience_gallery()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path TO '' AS $fn$
DECLARE v_count bigint; v_covers bigint;
BEGIN
  IF NEW.status <> 'applied' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' THEN
    IF OLD.status = 'applied' THEN RETURN NEW; END IF;
  END IF;
  SELECT count(*), count(*) FILTER (WHERE is_cover)
    INTO v_count,v_covers FROM public.experience_media WHERE experience_id=NEW.experience_id;
  IF v_count < 1 OR v_covers <> 1 THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='invalid-applied-experience-gallery';
  END IF;
  RETURN NEW;
END;
$fn$;

REVOKE EXECUTE ON FUNCTION public.guard_experience_review_metadata(), public.guard_experience_revision_metadata(), public.guard_applied_experience_gallery() FROM PUBLIC, anon, authenticated;

CREATE TRIGGER dt_rel_guard_experience_metadata BEFORE INSERT OR UPDATE ON public.experiences
FOR EACH ROW EXECUTE FUNCTION public.guard_experience_review_metadata();
CREATE TRIGGER dt_rel_guard_revision_metadata BEFORE INSERT OR UPDATE ON public.experience_revisions
FOR EACH ROW EXECUTE FUNCTION public.guard_experience_revision_metadata();
CREATE TRIGGER dt_rel_guard_applied_gallery BEFORE INSERT OR UPDATE OF status ON public.experience_revisions
FOR EACH ROW EXECUTE FUNCTION public.guard_applied_experience_gallery();

