-- Normalize legacy URLs generated by either approval RPC, including future approvals.
CREATE FUNCTION public.rel_storage02_normalize_cover_url() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $fn$
BEGIN
 IF NEW.image_url LIKE 'https://%/storage/v1/object/public/experience-media/%' THEN
  NEW.image_url := '/api/experience-photo?path=' || replace(replace(replace(replace(replace(split_part(NEW.image_url,'/storage/v1/object/public/experience-media/',2),'%','%25'),' ','%20'),'&','%26'),'#','%23'),'?','%3F');
 END IF;
 RETURN NEW;
END;
$fn$;
REVOKE EXECUTE ON FUNCTION public.rel_storage02_normalize_cover_url() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER rel_storage02_normalize_cover BEFORE INSERT OR UPDATE OF image_url ON public.experiences FOR EACH ROW EXECUTE FUNCTION public.rel_storage02_normalize_cover_url();
UPDATE public.experiences SET image_url=image_url WHERE image_url LIKE 'https://%/storage/v1/object/public/experience-media/%';
